    'RegistrationText'=>'يتم منح مثيلات SimpleRisk المسجلة على الفور الوصول إلى إضافات الترقية وإطار عمل عناصر التحكم الآمن (SCF). يوفر Upgrade Extra القدرة على النسخ الاحتياطي وترقية مثيل SimpleRisk الخاص بك بنقرة زر واحدة. يوفر إطار عمل الضوابط الآمنة (SCF) Extra إطار تحكم مشتركًا مدمجًا في وظيفة إدارة SimpleRisk. عند تسجيل SimpleRisk ، سيتم إرسال معلومات التسجيل الخاصة بك إلى خادم تستضيفه SimpleRisk. سيتم استخدام معلومات التسجيل المقدمة بواسطة SimpleRisk لإعلام العملاء بالإصدارات الجديدة والتحديثات الأمنية. ستؤدي عملية التسجيل في SimpleRisk إلى اختيارك في اتصالاتنا التسويقية ، ولكن يمكنك إلغاء الاشتراك في أي وقت باستخدام رابط إلغاء الاشتراك في هذه الاتصالات. تحترم SimpleRisk خصوصية عملائنا ولن يتم بيع المعلومات المقدمة إلينا من خلال عملية التسجيل في SimpleRisk إلى طرف ثالث.',
