    'SettingsDesc'                        => 'قم بتكوين الإعدادات على مستوى النظام: عنوان URL الأساسي، والأمان، واللغة الافتراضية، والمنطقة الزمنية، وإعدادات تسجيل المخاطر الافتراضية، والمزيد.',
    'SettingsPreferencesDesc'             => 'القيم الافتراضية والتفضيلات السلوكية عبر SimpleRisk: اللغة، والمنطقة الزمنية، وحالات التدقيق، ومتطلبات رسم خرائط المخاطر، ومفاتيح تبديل سلوك واجهة المستخدم، وما شابه ذلك.',
    'SettingsFileUploadDesc'              => 'أنواع الملفات المسموح بتحميلها وحدود حجمها في مختلف حقول إرفاق الملفات.',
