    'ApplicabilityErrFrameworkNotFound' => 'الإطار {$framework} غير موجود.',
    'ApplicabilityErrControlsNotFound' => 'معرفات التحكم هذه غير موجودة: {$ids}.',
    // Controls/Risks import result messages (validation gate, individual bad-row
