    'UpgradingTo' => 'الترقية إلى {version}',
    'UpgradeSafeToClose' => 'يمكنك إغلاق هذه النافذة بأمان. سيستمر التحديث على الخادم، وسيتم إعادة ربط هذه الصفحة.',
